package com.tagkeeper;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.mockito.ArgumentCaptor;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import org.mockito.ArgumentMatchers;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.util.Text;

/**
 * Tests the rename/delete/import config mutations end-to-end over a
 * ConfigManager mock backed by a plain map of "group.key" to value.
 */
public class TagMutationTest
{
	private final Map<String, String> store = new HashMap<>();
	private TagManager tagManager;
	private LayoutManager layoutManager;
	private TabKeeper tabKeeper;
	private TagTransfer tagTransfer;

	@Before
	public void setUp()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		when(configManager.getConfigurationKeys(anyString())).thenAnswer(inv ->
		{
			String prefix = inv.getArgument(0);
			return store.keySet().stream()
				.filter(k -> k.startsWith(prefix))
				.collect(java.util.stream.Collectors.toList());
		});
		when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(inv ->
			store.get(inv.getArgument(0) + "." + inv.getArgument(1)));
		when(configManager.getConfiguration(anyString(), anyString(), eq(Boolean.class))).thenAnswer(inv ->
		{
			String v = store.get(inv.getArgument(0) + "." + inv.getArgument(1));
			return v == null ? null : Boolean.parseBoolean(v);
		});
		when(configManager.getConfiguration(anyString(), anyString(), eq(Integer.class))).thenAnswer(inv ->
		{
			String v = store.get(inv.getArgument(0) + "." + inv.getArgument(1));
			return v == null ? null : Integer.parseInt(v);
		});
		doAnswer(inv ->
		{
			store.put(inv.getArgument(0) + "." + inv.getArgument(1), inv.getArgument(2));
			return null;
		}).when(configManager).setConfiguration(anyString(), anyString(), anyString());
		doAnswer(inv ->
		{
			store.put(inv.getArgument(0) + "." + inv.getArgument(1), String.valueOf((Object) inv.getArgument(2)));
			return null;
		}).when(configManager).setConfiguration(anyString(), anyString(), ArgumentMatchers.<Object>any());
		doAnswer(inv ->
		{
			store.remove(inv.getArgument(0) + "." + inv.getArgument(1));
			return null;
		}).when(configManager).unsetConfiguration(anyString(), anyString());

		tagManager = mock(TagManager.class);
		layoutManager = mock(LayoutManager.class);
		Client client = mock(Client.class);
		ClientThread clientThread = mock(ClientThread.class);
		BankTagsService bankTagsService = mock(BankTagsService.class);

		TagData tagData = new TagData(configManager);
		IconShadows iconShadows = new IconShadows(configManager, tagData);
		tabKeeper = new TabKeeper(client, clientThread, configManager,
			mock(ChatboxPanelManager.class), mock(ChatboxItemSearch.class),
			bankTagsService, tagManager, tagData, iconShadows);
		tagTransfer = new TagTransfer(client, clientThread, configManager,
			tagManager, layoutManager, tagData, tabKeeper);
	}

	@Test
	public void renameMovesAllConfigAndRewritesItemTags()
	{
		store.put("banktags.item_100", "gear,other");
		store.put("banktags.item_200", "gear*");
		store.put("banktags.tagtabs", "first,gear,last");
		store.put("banktags.icon_gear", "4151");
		store.put("banktags.layout_gear", "10,-1,20");
		store.put("banktags.hidden_gear", "true");
		store.put("banktaglayouts.layout_gear", "30:0");
		store.put("tagkeeper.icon_gear", "4151");

		tabKeeper.renameTag("gear", "melee");

		assertEquals(Arrays.asList("melee", "other"), Text.fromCSV(store.get("banktags.item_100")));
		assertEquals(Arrays.asList("melee*"), Text.fromCSV(store.get("banktags.item_200")));
		assertEquals(Arrays.asList("first", "melee", "last"), Text.fromCSV(store.get("banktags.tagtabs")));
		assertEquals("4151", store.get("banktags.icon_melee"));
		assertEquals("10,-1,20", store.get("banktags.layout_melee"));
		assertEquals("true", store.get("banktags.hidden_melee"));
		assertEquals("30:0", store.get("banktaglayouts.layout_melee"));
		assertEquals("4151", store.get("tagkeeper.icon_melee"));

		assertNull(store.get("banktags.icon_gear"));
		assertNull(store.get("banktags.layout_gear"));
		assertNull(store.get("banktags.hidden_gear"));
		assertNull(store.get("banktaglayouts.layout_gear"));
		assertNull(store.get("tagkeeper.icon_gear"));
	}

	@Test
	public void renameOntoExistingTagMergesAndTargetWins()
	{
		store.put("banktags.item_1", "gear");
		store.put("banktags.item_2", "melee,gear");
		store.put("banktags.tagtabs", "gear,melee");
		store.put("banktags.icon_gear", "100");
		store.put("banktags.icon_melee", "200");

		tabKeeper.renameTag("gear", "melee");

		assertEquals(Arrays.asList("melee"), Text.fromCSV(store.get("banktags.item_1")));
		assertEquals(Arrays.asList("melee"), Text.fromCSV(store.get("banktags.item_2")));
		assertEquals(Arrays.asList("melee"), Text.fromCSV(store.get("banktags.tagtabs")));
		assertEquals("200", store.get("banktags.icon_melee"));
		assertNull(store.get("banktags.icon_gear"));
	}

	@Test
	public void deleteRemovesTabAndAllConfig()
	{
		store.put("banktags.tagtabs", "gear,other");
		store.put("banktags.icon_gear", "100");
		store.put("banktags.layout_gear", "1,2");
		store.put("banktags.hidden_gear", "true");
		store.put("banktaglayouts.layout_gear", "3:0");
		store.put("tagkeeper.icon_gear", "100");

		tabKeeper.deleteTag("gear");

		verify(tagManager).removeTag("gear");
		assertEquals(Arrays.asList("other"), Text.fromCSV(store.get("banktags.tagtabs")));
		assertNull(store.get("banktags.icon_gear"));
		assertNull(store.get("banktags.layout_gear"));
		assertNull(store.get("banktags.hidden_gear"));
		assertNull(store.get("banktaglayouts.layout_gear"));
		assertNull(store.get("tagkeeper.icon_gear"));
	}

	@Test
	public void importCoreFormatTagsItemsAndRestoresLayout()
	{
		String name = tagTransfer.importCoreFormat(
			Text.fromCSV("banktags,1,Slayer,4151,995,-11,layout,0,1163").iterator());

		assertEquals("slayer", name);
		assertEquals("4151", store.get("banktags.icon_slayer"));
		verify(tagManager).addTag(995, "slayer", false);
		verify(tagManager).addTag(-11, "slayer", true);
		verify(tagManager).addTag(1163, "slayer", false);

		ArgumentCaptor<Layout> captor = ArgumentCaptor.forClass(Layout.class);
		verify(layoutManager).saveLayout(captor.capture());
		assertEquals(1163, captor.getValue().getItemAtPos(0));
	}

	@Test
	public void importBtlFormatRestoresBtlLayout()
	{
		String name = tagTransfer.importBtlFormat(
			Text.fromCSV("banktaglayoutsplugin:raids,4151:0,995:8,banktag:raids,12791,4151,995").iterator());

		assertEquals("raids", name);
		assertEquals("4151:0,995:8", store.get("banktaglayouts.layout_raids"));
		assertEquals("12791", store.get("banktags.icon_raids"));
		verify(tagManager).addTag(4151, "raids", false);
		verify(tagManager).addTag(995, "raids", false);
	}

	@Test
	public void importRejectsReservedNames()
	{
		String name = tagTransfer.importCoreFormat(
			Text.fromCSV("banktags,1,_invsetup_abc,4151,995").iterator());

		assertNull(name);
		verify(tagManager, never()).addTag(anyInt(), anyString(), anyBoolean());
		assertNull(store.get("banktags.icon__invsetup_abc"));
	}
}

package com.tagkeeper;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class TagDataTest
{
	@Test
	public void countPairEntriesCountsItemIndexPairs()
	{
		assertEquals(2, TagData.countPairEntries("123:0,456:7"));
		assertEquals(1, TagData.countPairEntries("123:0"));
	}

	@Test
	public void countPairEntriesIgnoresMalformedEntries()
	{
		assertEquals(0, TagData.countPairEntries(""));
		assertEquals(0, TagData.countPairEntries("123,456"));
		assertEquals(1, TagData.countPairEntries("123,456:2"));
	}

	@Test
	public void stripVarSuffixRemovesOnlyTrailingStar()
	{
		assertEquals("melee", TagData.stripVarSuffix("melee*"));
		assertEquals("melee", TagData.stripVarSuffix("melee"));
	}

	@Test
	public void nullToEmptyHandlesNull()
	{
		assertEquals("", TagData.nullToEmpty(null));
		assertEquals("x", TagData.nullToEmpty("x"));
	}
}

