package com.tagkeeper;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import net.runelite.client.config.ConfigManager;

/**
 * Tests TagData's aggregation over a ConfigManager mock backed by a plain
 * map of "group.key" to value.
 */
public class TagDataAggregationTest
{
	private final Map<String, String> store = new HashMap<>();
	private TagData tagData;

	@Before
	public void setUp()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		when(configManager.getConfigurationKeys(anyString())).thenAnswer(inv ->
		{
			String prefix = inv.getArgument(0);
			return store.keySet().stream()
				.filter(k -> k.startsWith(prefix))
				.collect(Collectors.toList());
		});
		when(configManager.getConfiguration(anyString(), anyString())).thenAnswer(inv ->
			store.get(inv.getArgument(0) + "." + inv.getArgument(1)));
		when(configManager.getConfiguration(anyString(), anyString(), eq(Boolean.class))).thenAnswer(inv ->
		{
			String v = store.get(inv.getArgument(0) + "." + inv.getArgument(1));
			return v == null ? null : Boolean.parseBoolean(v);
		});
		when(configManager.getConfiguration(anyString(), anyString(), eq(Integer.class))).thenAnswer(inv ->
		{
			String v = store.get(inv.getArgument(0) + "." + inv.getArgument(1));
			return v == null ? null : Integer.parseInt(v);
		});
		tagData = new TagData(configManager);
	}

	private TagData.TagInfo find(List<TagData.TagInfo> tags, String name)
	{
		return tags.stream().filter(t -> t.getName().equals(name)).findFirst().orElse(null);
	}

	@Test
	public void tagsMergesTabsAndItemTags()
	{
		store.put("banktags.tagtabs", "alpha");
		store.put("banktags.item_100", "beta");
		store.put("banktags.item_200", "beta,alpha");

		List<TagData.TagInfo> tags = tagData.tags();
		assertEquals(2, tags.size());

		TagData.TagInfo alpha = find(tags, "alpha");
		assertTrue(alpha.isTab());
		assertEquals(1, alpha.getItemCount());

		TagData.TagInfo beta = find(tags, "beta");
		assertFalse(beta.isTab());
		assertEquals(2, beta.getItemCount());
	}

	@Test
	public void tagsAreSortedAndStandardized()
	{
		store.put("banktags.item_1", "Zulrah");
		store.put("banktags.item_2", "abyss*");

		List<TagData.TagInfo> tags = tagData.tags();
		assertEquals("abyss", tags.get(0).getName());
		assertEquals("zulrah", tags.get(1).getName());
	}

	@Test
	public void hiddenTagsAreExcludedUnlessTheyAreTabs()
	{
		store.put("banktags.item_1", "_invsetup_abc,visible");
		store.put("banktags.hidden__invsetup_abc", "true");
		store.put("banktags.tagtabs", "hiddentab");
		store.put("banktags.hidden_hiddentab", "true");

		List<TagData.TagInfo> tags = tagData.tags();
		assertNull(find(tags, "_invsetup_abc"));

		TagData.TagInfo hiddenTab = find(tags, "hiddentab");
		assertTrue(hiddenTab.isHidden());
		assertTrue(hiddenTab.isTab());

		assertFalse(find(tags, "visible").isHidden());
	}

	@Test
	public void layoutCountsComeFromBothPluginsAndBtlWins()
	{
		store.put("banktags.item_1", "corelayout,btllayout,both,none");
		store.put("banktags.layout_corelayout", "10,-1,20,-1");
		store.put("banktaglayouts.layout_btllayout", "30:0,40:5");
		store.put("banktags.layout_both", "1,2,3");
		store.put("banktaglayouts.layout_both", "9:0");

		List<TagData.TagInfo> tags = tagData.tags();
		assertEquals((Integer) 2, find(tags, "corelayout").getLayoutItemCount());
		assertEquals((Integer) 2, find(tags, "btllayout").getLayoutItemCount());
		assertEquals((Integer) 1, find(tags, "both").getLayoutItemCount());
		assertNull(find(tags, "none").getLayoutItemCount());
	}

	@Test
	public void displayIconPrefersLiveIconOverShadow()
	{
		store.put("banktags.icon_live", "100");
		store.put("tagkeeper.icon_live", "200");
		store.put("tagkeeper.icon_shadowonly", "300");

		assertEquals((Integer) 100, tagData.displayIcon("live"));
		assertEquals((Integer) 300, tagData.displayIcon("shadowonly"));
		assertNull(tagData.displayIcon("neither"));
	}

	@Test
	public void tagExistsChecksTabsAndItemTags()
	{
		store.put("banktags.tagtabs", "tabonly");
		store.put("banktags.item_1", "itemonly");

		assertTrue(tagData.tagExists("tabonly"));
		assertTrue(tagData.tagExists("itemonly"));
		assertFalse(tagData.tagExists("nowhere"));
	}

	@Test
	public void allKnownTagsIncludesLayoutOnlyTags()
	{
		store.put("banktags.tagtabs", "tab");
		store.put("banktags.item_1", "item");
		store.put("banktaglayouts.layout_layoutonly", "1:0");

		assertTrue(tagData.allKnownTags().containsAll(List.of("tab", "item", "layoutonly")));
	}
}

package com.tagkeeper;

import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class TabKeeperTest
{
	@Test
	public void renameItemTagCsvRenamesTag()
	{
		assertEquals("stab,range", TabKeeper.renameItemTagCsv("melee,range", "melee", "stab"));
	}

	@Test
	public void renameItemTagCsvKeepsVariationSuffix()
	{
		assertEquals("stab*,mage", TabKeeper.renameItemTagCsv("melee*,mage", "melee", "stab"));
	}

	@Test
	public void renameItemTagCsvMatchesCaseInsensitively()
	{
		assertEquals("stab", TabKeeper.renameItemTagCsv("Melee", "melee", "stab"));
	}

	@Test
	public void renameItemTagCsvStandardizesOtherTags()
	{
		assertEquals("mage,stab", TabKeeper.renameItemTagCsv("MAGE,melee", "melee", "stab"));
	}

	@Test
	public void renameItemTagCsvMergeDeduplicates()
	{
		assertEquals("stab", TabKeeper.renameItemTagCsv("melee,stab", "melee", "stab"));
		assertEquals("stab*", TabKeeper.renameItemTagCsv("melee*,stab*", "melee", "stab"));
	}

	@Test
	public void renameItemTagCsvKeepsSuffixedAndPlainDistinct()
	{
		assertEquals("stab,stab*", TabKeeper.renameItemTagCsv("melee,melee*", "melee", "stab"));
	}

	@Test
	public void renameItemTagCsvReturnsNullWhenUntouched()
	{
		assertNull(TabKeeper.renameItemTagCsv("mage,range", "melee", "stab"));
		assertNull(TabKeeper.renameItemTagCsv("", "melee", "stab"));
		assertNull(TabKeeper.renameItemTagCsv(null, "melee", "stab"));
	}

	@Test
	public void renameInTabListRenamesInPlace()
	{
		assertEquals(Arrays.asList("a", "x", "c"),
			TabKeeper.renameInTabList(Arrays.asList("a", "b", "c"), "b", "x"));
	}

	@Test
	public void renameInTabListMergeDropsOldEntry()
	{
		assertEquals(Arrays.asList("a", "x"),
			TabKeeper.renameInTabList(Arrays.asList("a", "b", "x"), "b", "x"));
	}

	@Test
	public void renameInTabListMatchesCaseInsensitively()
	{
		assertEquals(Arrays.asList("x"),
			TabKeeper.renameInTabList(Arrays.asList("B"), "b", "x"));
	}

	@Test
	public void renameInTabListReturnsNullWhenNotATab()
	{
		assertNull(TabKeeper.renameInTabList(Arrays.asList("a", "c"), "b", "x"));
		assertNull(TabKeeper.renameInTabList(Arrays.asList(), "b", "x"));
	}
}

package com.tagkeeper;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollBar;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.plaf.basic.BasicScrollBarUI;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.FlatTextField;
import net.runelite.client.ui.components.PluginErrorPanel;

class TagkeeperPanel extends PluginPanel
{
	private static final String BANK_CLOSED_MESSAGE = "Your bank needs to be open.";

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final BankTagsService bankTagsService;
	private final TabKeeper tabKeeper;
	private final TagTransfer tagTransfer;
	private final TagData tagData;

	private final FlatTextField searchBar = new FlatTextField();
	private final JPanel container = new JPanel();
	private final PluginErrorPanel emptyPanel = new PluginErrorPanel();
	private JScrollPane scrollPane;

	// model cached by reload(); render() only re-applies the search filter
	private List<TagData.TagInfo> tags = Collections.emptyList();
	private String activeTag = "";

	private boolean compactView;

	// coalesces the bursts of config change events a rename produces
	private final Timer reloadDebounce = new Timer(150, e -> reload());

	@Inject
	TagkeeperPanel(Client client, ClientThread clientThread, ConfigManager configManager,
		ItemManager itemManager, BankTagsService bankTagsService, TabKeeper tabKeeper,
		TagTransfer tagTransfer, TagData tagData)
	{
		super(false);
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.bankTagsService = bankTagsService;
		this.tabKeeper = tabKeeper;
		this.tagTransfer = tagTransfer;
		this.tagData = tagData;

		compactView = Boolean.TRUE.equals(configManager.getConfiguration(
			TagData.CONFIG_GROUP, TagData.COMPACT_VIEW_KEY, Boolean.class));

		reloadDebounce.setRepeats(false);

		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(10, 10, 10, 10));
		// PluginPanel(false) sets no background at all - do it all explicitly
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		configureSearchBar();
		add(buildNorthPanel(), BorderLayout.NORTH);

		scrollPane = buildContentArea();
		add(scrollPane, BorderLayout.CENTER);

		emptyPanel.setContent(TagkeeperPlugin.PLUGIN_NAME, "No bank tags found. Tag items in your bank to get started.");

		reload();
	}

	private void configureSearchBar()
	{
		searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchBar.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		searchBar.getTextField().setForeground(Color.WHITE);
		searchBar.getTextField().setCaretColor(Color.WHITE);
		searchBar.getTextField().getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				render();
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				render();
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				render();
			}
		});
	}

	private JPanel buildNorthPanel()
	{
		JPanel northPanel = new JPanel();
		northPanel.setLayout(new BoxLayout(northPanel, BoxLayout.Y_AXIS));
		northPanel.setBorder(new EmptyBorder(0, 0, 10, 0));
		northPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		northPanel.add(buildSearchRow());
		return northPanel;
	}

	private JPanel buildSearchRow()
	{
		JLabel searchIcon = new JLabel(Icons.SEARCH);
		searchIcon.setBorder(new EmptyBorder(0, 8, 0, 4));

		JPanel searchActions = new JPanel(new GridLayout(1, 2, 6, 0));
		searchActions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchActions.setBorder(new EmptyBorder(0, 4, 0, 8));
		searchActions.add(buildImportButton());
		searchActions.add(buildViewToggle());

		JPanel searchRow = new JPanel(new BorderLayout());
		searchRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		searchRow.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 30));
		searchRow.add(searchIcon, BorderLayout.WEST);
		searchRow.add(searchBar, BorderLayout.CENTER);
		searchRow.add(searchActions, BorderLayout.EAST);
		return searchRow;
	}

	private JLabel buildViewToggle()
	{
		JLabel viewToggle = new JLabel();
		updateViewToggle(viewToggle);
		viewToggle.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		viewToggle.addMouseListener(onLeftClick(() ->
		{
			compactView = !compactView;
			configManager.setConfiguration(TagData.CONFIG_GROUP, TagData.COMPACT_VIEW_KEY, compactView);
			updateViewToggle(viewToggle);
			render();
		}));
		return viewToggle;
	}

	private void updateViewToggle(JLabel toggle)
	{
		toggle.setIcon(compactView ? Icons.CARD_VIEW : Icons.COMPACT_VIEW);
		toggle.setToolTipText(compactView ? "Switch to card view" : "Switch to compact view");
	}

	private JLabel buildImportButton()
	{
		JLabel importButton = new JLabel(Icons.IMPORT);
		importButton.setToolTipText("Import tag from clipboard");
		importButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		importButton.addMouseListener(onLeftClick(tagTransfer::importFromClipboard));
		return importButton;
	}

	private JScrollPane buildContentArea()
	{
		container.setLayout(new DynamicGridLayout(0, 1, 0, 10));
		container.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JPanel contentWrapper = new ViewportWidthPanel();
		contentWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
		contentWrapper.add(container, BorderLayout.NORTH);

		JScrollPane pane = new JScrollPane(contentWrapper);
		pane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		pane.setBorder(null);
		pane.setBackground(ColorScheme.DARK_GRAY_COLOR);
		pane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
		styleScrollBar(pane.getVerticalScrollBar());
		return pane;
	}

	private static void styleScrollBar(JScrollBar bar)
	{
		bar.setPreferredSize(new Dimension(7, 0));
		bar.setUI(new BasicScrollBarUI()
		{
			@Override
			protected void paintThumb(Graphics g, JComponent c, Rectangle thumbBounds)
			{
				g.setColor(ColorScheme.DARKER_GRAY_HOVER_COLOR);
				g.fillRect(thumbBounds.x, thumbBounds.y, thumbBounds.width, thumbBounds.height);
			}

			@Override
			protected void paintTrack(Graphics g, JComponent c, Rectangle trackBounds)
			{
				g.setColor(ColorScheme.DARK_GRAY_COLOR);
				g.fillRect(trackBounds.x, trackBounds.y, trackBounds.width, trackBounds.height);
			}

			@Override
			protected JButton createDecreaseButton(int orientation)
			{
				return invisibleButton();
			}

			@Override
			protected JButton createIncreaseButton(int orientation)
			{
				return invisibleButton();
			}
		});
	}

	private static JButton invisibleButton()
	{
		JButton button = new JButton();
		button.setPreferredSize(new Dimension(0, 0));
		button.setMinimumSize(new Dimension(0, 0));
		button.setMaximumSize(new Dimension(0, 0));
		return button;
	}

	/**
	 * Keeps the scroll view exactly as wide as the viewport. A plain JPanel
	 * view grows to its preferred width when a long tag name exceeds it,
	 * silently pushing every card's right edge out of the visible area.
	 */
	private static class ViewportWidthPanel extends JPanel implements Scrollable
	{
		ViewportWidthPanel()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static MouseAdapter onLeftClick(Runnable action)
	{
		return new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					action.run();
				}
			}
		};
	}

	@Override
	public void onActivate()
	{
		reload();
	}

	// safe to call from any thread
	void reloadSoon()
	{
		SwingUtilities.invokeLater(reloadDebounce::restart);
	}

	// the active tag is client state - capture it on the client thread
	// before the config reads and rendering happen on the EDT
	void reload()
	{
		clientThread.invoke(() ->
		{
			String active = tabKeeper.standardizedActiveTag();
			SwingUtilities.invokeLater(() ->
			{
				activeTag = active;
				tags = tagData.tags();
				render();
			});
		});
	}

	void shutDown()
	{
		reloadDebounce.stop();
	}

	private void render()
	{
		int scroll = scrollPane == null ? 0 : scrollPane.getVerticalScrollBar().getValue();
		container.removeAll();
		container.setLayout(new DynamicGridLayout(0, 1, 0, compactView ? 4 : 10));

		String filter = searchBar.getText() == null ? "" : searchBar.getText().toLowerCase(Locale.ROOT).trim();

		if (tags.isEmpty())
		{
			container.add(emptyPanel);
			revalidate();
			repaint();
			return;
		}

		int shown = 0;
		for (TagData.TagInfo tag : tags)
		{
			if (!filter.isEmpty() && !tag.getName().contains(filter))
			{
				continue;
			}
			container.add(new TagCard(this, tabKeeper, tagTransfer, itemManager, tag, tag.getName().equals(activeTag), compactView));
			shown++;
		}

		if (shown == 0)
		{
			JLabel none = new JLabel("No tags match \"" + filter + "\"");
			none.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			none.setHorizontalAlignment(SwingConstants.CENTER);
			container.add(none);
		}

		revalidate();
		repaint();
		// restore the scroll position once the new layout has been computed
		SwingUtilities.invokeLater(() -> scrollPane.getVerticalScrollBar().setValue(scroll));
	}

	void toggleTag(String tag)
	{
		clientThread.invoke(() ->
		{
			if (client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER) == null)
			{
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					tabKeeper.chatMessage(BANK_CLOSED_MESSAGE);
				}
				else
				{
					TabKeeper.showDialog(BANK_CLOSED_MESSAGE);
				}
				return;
			}

			if (tag.equals(tabKeeper.standardizedActiveTag()))
			{
				bankTagsService.closeBankTag();
			}
			else
			{
				bankTagsService.openBankTag(tag, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
			}
			reload();
		});
	}

}

package com.tagkeeper;

import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.plugins.banktags.tabs.TabInterface;
import net.runelite.client.util.Text;

/**
 * Clipboard import and export of tags, in core Bank Tags' format and the
 * Bank Tag Layouts plugin's.
 */
@Slf4j
@Singleton
class TagTransfer
{
	private static final String CORE_EXPORT_HEADER = "banktags";
	private static final String LAYOUT_MARKER = "layout";
	private static final String BTL_EXPORT_PREFIX = "banktaglayoutsplugin:";
	private static final String BTL_BANKTAG_SECTION = "banktag:";

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final TagManager tagManager;
	private final LayoutManager layoutManager;
	private final TagData tagData;
	private final TabKeeper tabKeeper;

	@Inject
	TagTransfer(Client client, ClientThread clientThread, ConfigManager configManager,
		TagManager tagManager, LayoutManager layoutManager, TagData tagData, TabKeeper tabKeeper)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
		this.tagData = tagData;
		this.tabKeeper = tabKeeper;
	}

	// a Bank Tag Layouts layout is exported in that plugin's format so it
	// round-trips; anything else uses core Bank Tags' format
	void exportTag(String tag)
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			String btlLayout = configManager.getConfiguration(
				TagData.BTL_CONFIG_GROUP, TagData.BTL_LAYOUT_PREFIX + tag);
			if (btlLayout != null)
			{
				exportBtlFormat(tag, btlLayout);
			}
			else
			{
				exportCoreFormat(tag);
			}
		});
	}

	// banktags,1,tag,icon,item,...[,layout,idx,item,...]
	private void exportCoreFormat(String tag)
	{
		List<String> data = new ArrayList<>();
		data.add(CORE_EXPORT_HEADER);
		data.add("1");
		data.add(tag);
		data.add(exportIconFor(tag));

		Layout layout = layoutManager.loadLayout(tag);
		for (Integer item : tagManager.getItemsForTag(tag))
		{
			// like core: items placed in the layout are implied by it
			if (layout == null || layout.count(item) == 0)
			{
				data.add(String.valueOf(item));
			}
		}
		if (layout != null)
		{
			appendCoreLayout(data, layout);
		}

		copyToClipboard(Text.toCSV(data));
		tabKeeper.chatMessage("Tag \"" + tag + "\" has been copied to your clipboard!");
	}

	private static void appendCoreLayout(List<String> data, Layout layout)
	{
		data.add(LAYOUT_MARKER);
		int[] l = layout.getLayout();
		for (int idx = 0; idx < l.length; ++idx)
		{
			if (l[idx] != -1)
			{
				data.add(String.valueOf(idx));
				data.add(String.valueOf(l[idx]));
			}
		}
	}

	// banktaglayoutsplugin:tag,id:idx,...,banktag:tag,icon,item,...
	private void exportBtlFormat(String tag, String btlLayout)
	{
		StringBuilder sb = new StringBuilder(BTL_EXPORT_PREFIX).append(tag);
		if (!btlLayout.isEmpty())
		{
			sb.append(',').append(btlLayout);
		}

		List<String> data = new ArrayList<>();
		data.add(tag);
		data.add(exportIconFor(tag));
		for (Integer item : tagManager.getItemsForTag(tag))
		{
			data.add(String.valueOf(item));
		}
		sb.append(',').append(BTL_BANKTAG_SECTION).append(Text.toCSV(data));

		copyToClipboard(sb.toString());
		tabKeeper.chatMessage("Tag \"" + tag + "\" and its layout have been copied to your clipboard!");
	}

	private String exportIconFor(String tag)
	{
		Integer icon = tagData.displayIcon(tag);
		return String.valueOf(icon != null ? icon : ItemID.SPADE);
	}

	private static void copyToClipboard(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}

	// a BTL-format layout is restored into that plugin's own config group,
	// unlike core's import which converts it to a core layout
	void importFromClipboard()
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			String name = readAndImportClipboard();
			if (name == null)
			{
				tabKeeper.chatMessage("Failed to import tag from clipboard, invalid format.");
				return;
			}
			tabKeeper.addTabToBank(name);
			tabKeeper.chatMessage("Tag \"" + name + "\" has been imported from your clipboard!");
		});
	}

	private String readAndImportClipboard()
	{
		try
		{
			String data = Toolkit.getDefaultToolkit().getSystemClipboard()
				.getData(DataFlavor.stringFlavor).toString().trim();
			Iterator<String> iter = Text.fromCSV(data).iterator();
			return data.startsWith(BTL_EXPORT_PREFIX)
				? importBtlFormat(iter)
				: importCoreFormat(iter);
		}
		catch (UnsupportedFlavorException | IOException | NoSuchElementException | NumberFormatException ex)
		{
			log.debug("failed to import tag", ex);
			return null;
		}
	}

	// banktags,1,tag,icon,item,...[,layout,idx,item,...]
	String importCoreFormat(Iterator<String> iter)
	{
		String name = iter.next();
		if (CORE_EXPORT_HEADER.equals(name))
		{
			iter.next(); // version
			name = iter.next();
		}
		name = filterTagName(name);
		if (name == null)
		{
			return null;
		}

		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(name),
			Integer.parseInt(iter.next()));

		if (importCoreItems(name, iter))
		{
			importCoreLayout(name, iter);
		}
		return name;
	}

	// returns true when the layout marker was reached
	private boolean importCoreItems(String name, Iterator<String> iter)
	{
		while (iter.hasNext())
		{
			String token = iter.next();
			if (LAYOUT_MARKER.equals(token))
			{
				return true;
			}
			int itemId = Integer.parseInt(token);
			tagManager.addTag(itemId, name, itemId < 0);
		}
		return false;
	}

	private void importCoreLayout(String name, Iterator<String> iter)
	{
		Layout layout = new Layout(name);
		while (iter.hasNext())
		{
			int idx = Integer.parseInt(iter.next());
			int itemId = Integer.parseInt(iter.next());
			layout.setItemAtPos(itemId, idx);
			tagManager.addTag(itemId, name, false);
		}
		layoutManager.saveLayout(layout);
	}

	// banktaglayoutsplugin:tag,id:idx,...,banktag:tag,icon,item,...
	String importBtlFormat(Iterator<String> iter)
	{
		String header = iter.next();
		String name = filterTagName(header.substring(BTL_EXPORT_PREFIX.length()));
		if (name == null)
		{
			return null;
		}

		List<String> layoutPairs = readBtlLayoutPairs(iter);
		if (layoutPairs == null)
		{
			return null;
		}
		if (!layoutPairs.isEmpty())
		{
			configManager.setConfiguration(TagData.BTL_CONFIG_GROUP,
				TagData.BTL_LAYOUT_PREFIX + name, String.join(",", layoutPairs));
		}

		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(name),
			Integer.parseInt(iter.next()));

		while (iter.hasNext())
		{
			int itemId = Integer.parseInt(iter.next());
			tagManager.addTag(itemId, name, itemId < 0);
		}
		return name;
	}

	// returns null when the banktag: section never appears
	private static List<String> readBtlLayoutPairs(Iterator<String> iter)
	{
		List<String> layoutPairs = new ArrayList<>();
		while (iter.hasNext())
		{
			String token = iter.next();
			if (token.startsWith(BTL_BANKTAG_SECTION))
			{
				return layoutPairs;
			}
			// parse to validate the id:idx pair
			String[] pair = token.split(":");
			Integer.parseInt(pair[0]);
			Integer.parseInt(pair[1]);
			layoutPairs.add(token);
		}
		return null;
	}

	private static String filterTagName(String raw)
	{
		StringBuilder sb = new StringBuilder();
		for (char c : raw.toCharArray())
		{
			if (TabInterface.FILTERED_CHARS.test(c))
			{
				sb.append(c);
			}
		}
		String name = Text.standardize(sb.toString());
		return name.isEmpty() || name.startsWith("_") ? null : name;
	}
}

package com.tagkeeper;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import java.util.TreeSet;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.util.Text;

/**
 * Read-side access to the tag config of core Bank Tags, the Bank Tag
 * Layouts hub plugin, and our own group.
 */
@Singleton
class TagData
{
	// our own config group; IconShadows keeps the shadow icon copies here,
	// the panel its view mode
	static final String CONFIG_GROUP = "tagkeeper";
	static final String ICON_PREFIX = "icon_";
	static final String COMPACT_VIEW_KEY = "compactView";

	// package-private in BankTagsPlugin, see its config schema comment:
	// banktags:item_<id>=tag,tag,tag,...
	// banktags:hidden_<tag>=true
	static final String ITEM_KEY_PREFIX = "item_";
	static final String TAG_HIDDEN_PREFIX = "hidden_";

	// The hub plugin "Bank Tag Layouts" (com.banktaglayouts.BankTagLayoutsPlugin)
	// stores layouts in its own group as itemId:index,itemId:index,...
	static final String BTL_CONFIG_GROUP = "banktaglayouts";
	static final String BTL_LAYOUT_PREFIX = "layout_";

	private final ConfigManager configManager;

	@Inject
	TagData(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	@Value
	static class TagInfo
	{
		String name;
		boolean tab;
		boolean hidden;
		Integer iconItemId;
		Integer layoutItemCount;
		int itemCount;
	}

	List<TagInfo> tags()
	{
		Set<String> tabSet = tabSet();
		Map<String, Integer> itemCounts = itemTagCounts();
		Set<String> allTags = new TreeSet<>(tabSet);
		allTags.addAll(itemCounts.keySet());
		Map<String, Integer> layouts = layouts();

		List<TagInfo> result = new ArrayList<>(allTags.size());
		for (String tag : allTags)
		{
			boolean tab = tabSet.contains(tag);
			boolean hidden = isHidden(tag);
			if (hidden && !tab)
			{
				// hidden marks plugin-internal machine tags; core filters them
				// from every user-facing list, so do we. A tab is always
				// shown - it is visibly in the bank.
				continue;
			}
			result.add(new TagInfo(tag, tab, hidden, displayIcon(tag), layouts.get(tag),
				itemCounts.getOrDefault(tag, 0)));
		}
		return result;
	}

	boolean tagExists(String standardizedTag)
	{
		return tabSet().contains(standardizedTag) || itemTagCounts().containsKey(standardizedTag);
	}

	Set<String> allKnownTags()
	{
		Set<String> known = new HashSet<>(tabSet());
		known.addAll(itemTagCounts().keySet());
		known.addAll(layouts().keySet());
		return known;
	}

	// in bank order, raw as stored (not standardized)
	List<String> tabList()
	{
		return new ArrayList<>(Text.fromCSV(nullToEmpty(
			configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG))));
	}

	private Set<String> tabSet()
	{
		Set<String> tabSet = new HashSet<>();
		for (String tab : tabList())
		{
			tabSet.add(Text.standardize(tab));
		}
		return tabSet;
	}

	// variation-group entries (negative item ids) count as one item
	private Map<String, Integer> itemTagCounts()
	{
		Map<String, Integer> counts = new TreeMap<>();
		for (String cfgKey : keysWithPrefix(BankTagsPlugin.CONFIG_GROUP, ITEM_KEY_PREFIX))
		{
			for (String tag : Text.fromCSV(nullToEmpty(
				configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, cfgKey))))
			{
				tag = Text.standardize(stripVarSuffix(tag));
				if (!tag.isEmpty())
				{
					counts.merge(tag, 1, Integer::sum);
				}
			}
		}
		return counts;
	}

	private Map<String, Integer> layouts()
	{
		Map<String, Integer> layouts = new TreeMap<>();

		// core banktags layouts: positional item id CSV, -1 marks an empty slot
		for (String cfgKey : keysWithPrefix(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_LAYOUT_PREFIX))
		{
			String tag = cfgKey.substring(BankTagsPlugin.TAG_LAYOUT_PREFIX.length());
			int items = 0;
			for (String id : Text.fromCSV(nullToEmpty(
				configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, cfgKey))))
			{
				if (!"-1".equals(id))
				{
					items++;
				}
			}
			layouts.put(tag, items);
		}

		for (String cfgKey : keysWithPrefix(BTL_CONFIG_GROUP, BTL_LAYOUT_PREFIX))
		{
			String tag = cfgKey.substring(BTL_LAYOUT_PREFIX.length());
			layouts.put(tag, countPairEntries(nullToEmpty(
				configManager.getConfiguration(BTL_CONFIG_GROUP, cfgKey))));
		}
		return layouts;
	}

	boolean isHidden(String standardizedTag)
	{
		return Boolean.TRUE.equals(configManager.getConfiguration(
			BankTagsPlugin.CONFIG_GROUP, TAG_HIDDEN_PREFIX + standardizedTag, Boolean.class));
	}

	// the live tab icon if present, otherwise the shadow copy IconShadows remembers
	Integer displayIcon(String tag)
	{
		Integer id = configManager.getConfiguration(
			BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX + tag, Integer.class);
		if (id == null)
		{
			id = configManager.getConfiguration(CONFIG_GROUP, ICON_PREFIX + tag, Integer.class);
		}
		return id;
	}

	static String iconKey(String tag)
	{
		return BankTagsPlugin.TAG_ICON_PREFIX + tag;
	}

	static String shadowIconKey(String tag)
	{
		return ICON_PREFIX + tag;
	}

	// the returned keys have the group part already stripped
	List<String> keysWithPrefix(String group, String prefix)
	{
		List<String> keys = new ArrayList<>();
		for (String key : configManager.getConfigurationKeys(group + "." + prefix))
		{
			keys.add(key.split("\\.", 2)[1]);
		}
		return keys;
	}

	static int countPairEntries(String layoutString)
	{
		int items = 0;
		for (String entry : layoutString.split(","))
		{
			if (entry.contains(":"))
			{
				items++;
			}
		}
		return items;
	}

	static String stripVarSuffix(String tag)
	{
		return tag.endsWith(BankTagsPlugin.VAR_TAG_SUFFIX)
			? tag.substring(0, tag.length() - BankTagsPlugin.VAR_TAG_SUFFIX.length())
			: tag;
	}

	static String nullToEmpty(String s)
	{
		return s == null ? "" : s;
	}
}

package com.tagkeeper;

import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.util.Text;

/**
 * Shadow copies of tab icons in our own config group: core Bank Tags
 * deletes icon_<tag> when a tab is removed and falls back to a spade when
 * it is re-added, so the remembered icon is restored instead.
 */
@Slf4j
@Singleton
class IconShadows
{
	private static final String DEFAULT_ICON = String.valueOf(ItemID.SPADE);

	private final ConfigManager configManager;
	private final TagData tagData;

	@Inject
	IconShadows(ConfigManager configManager, TagData tagData)
	{
		this.configManager = configManager;
		this.tagData = tagData;
	}

	// picks up icons set while the plugin was disabled
	void snapshotAll()
	{
		for (String cfgKey : tagData.keysWithPrefix(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_ICON_PREFIX))
		{
			String tag = cfgKey.substring(BankTagsPlugin.TAG_ICON_PREFIX.length());
			String value = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, cfgKey);
			if (value != null)
			{
				save(tag, value);
			}
		}
	}

	void snapshot(String tag)
	{
		String icon = configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(tag));
		if (icon != null)
		{
			save(tag, icon);
		}
	}

	// a deleted tag's icon must not resurface on a future tag reusing the name
	void gc()
	{
		Set<String> known = tagData.allKnownTags();
		for (String cfgKey : tagData.keysWithPrefix(TagData.CONFIG_GROUP, TagData.ICON_PREFIX))
		{
			String tag = cfgKey.substring(TagData.ICON_PREFIX.length());
			if (!known.contains(tag)
				&& configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(tag)) == null)
			{
				log.debug("Dropping shadow icon of deleted tag {}", tag);
				configManager.unsetConfiguration(TagData.CONFIG_GROUP, cfgKey);
			}
		}
	}

	// returns true when the bank's tab strip needs a redraw
	boolean onBankTagsConfigChanged(ConfigChanged event)
	{
		String key = event.getKey();
		if (key.startsWith(BankTagsPlugin.TAG_ICON_PREFIX))
		{
			return onIconChanged(key, event.getNewValue());
		}
		if (BankTagsPlugin.TAG_TABS_CONFIG.equals(key))
		{
			boolean restored = false;
			for (String tab : Text.fromCSV(TagData.nullToEmpty(event.getNewValue())))
			{
				restored |= restoreIfMissing(Text.standardize(tab));
			}
			return restored;
		}
		return false;
	}

	private boolean onIconChanged(String key, String newValue)
	{
		String tag = key.substring(BankTagsPlugin.TAG_ICON_PREFIX.length());
		String saved = configManager.getConfiguration(TagData.CONFIG_GROUP, TagData.shadowIconKey(tag));
		if (newValue == null || newValue.equals(saved))
		{
			return false;
		}
		if (DEFAULT_ICON.equals(newValue) && saved != null)
		{
			// the default spade just replaced an icon we remember - restore ours
			log.debug("Restoring icon {} for tab {}", saved, tag);
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, key, saved);
			return true;
		}
		save(tag, newValue);
		return false;
	}

	boolean restoreIfMissing(String tag)
	{
		if (configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(tag)) != null)
		{
			return false;
		}
		String saved = configManager.getConfiguration(TagData.CONFIG_GROUP, TagData.shadowIconKey(tag));
		if (saved == null)
		{
			return false;
		}
		log.debug("Restoring icon {} for tab {}", saved, tag);
		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(tag), saved);
		return true;
	}

	private void save(String tag, String value)
	{
		configManager.setConfiguration(TagData.CONFIG_GROUP, TagData.shadowIconKey(tag), value);
	}
}

package com.tagkeeper;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.util.ImageUtil;

/**
 * Icons drawn at runtime (no image assets). Action icons follow the
 * Inventory Setups recipe: on, on-hover, off (= dimmed), off-hover.
 */
final class Icons
{
	static final ImageIcon EYE;
	static final ImageIcon EYE_HOVER;
	static final ImageIcon NO_EYE;
	static final ImageIcon NO_EYE_HOVER;

	static final ImageIcon TAB;
	static final ImageIcon TAB_HOVER;
	static final ImageIcon NO_TAB;
	static final ImageIcon NO_TAB_HOVER;

	static final ImageIcon LAYOUT;
	static final ImageIcon NO_LAYOUT;

	static final ImageIcon SEARCH;

	// view mode toggle: shows the mode you would switch to
	static final ImageIcon COMPACT_VIEW;
	static final ImageIcon CARD_VIEW;

	static final ImageIcon IMPORT;

	static final BufferedImage NAV;

	static
	{
		final BufferedImage eyeImg = drawEye();
		final BufferedImage eyeDim = ImageUtil.luminanceOffset(eyeImg, -150);
		EYE = new ImageIcon(eyeImg);
		EYE_HOVER = new ImageIcon(eyeDim);
		NO_EYE = new ImageIcon(eyeDim);
		NO_EYE_HOVER = new ImageIcon(ImageUtil.alphaOffset(eyeDim, -100));

		final BufferedImage tabImg = drawBookmark();
		final BufferedImage tabDim = ImageUtil.luminanceOffset(tabImg, -150);
		TAB = new ImageIcon(tabImg);
		TAB_HOVER = new ImageIcon(tabDim);
		NO_TAB = new ImageIcon(tabDim);
		NO_TAB_HOVER = new ImageIcon(ImageUtil.alphaOffset(tabDim, -100));

		final BufferedImage layoutImg = drawGrid();
		LAYOUT = new ImageIcon(layoutImg);
		NO_LAYOUT = new ImageIcon(ImageUtil.alphaOffset(ImageUtil.luminanceOffset(layoutImg, -150), -100));

		SEARCH = new ImageIcon(drawMagnifier());
		COMPACT_VIEW = new ImageIcon(drawLines());
		CARD_VIEW = new ImageIcon(drawCard());
		IMPORT = new ImageIcon(drawImport());
		NAV = drawNav();
	}

	private Icons()
	{
	}

	private static BufferedImage drawEye()
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(219, 219, 219));
		g.drawOval(1, 4, 11, 6);
		g.fillOval(5, 5, 4, 4);
		g.dispose();
		return img;
	}

	private static BufferedImage drawBookmark()
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(219, 219, 219));
		g.fillPolygon(new Polygon(
			new int[]{3, 11, 11, 7, 3},
			new int[]{1, 1, 13, 10, 13},
			5));
		g.dispose();
		return img;
	}

	private static BufferedImage drawGrid()
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(new Color(219, 219, 219));
		g.fillRect(2, 2, 4, 4);
		g.fillRect(8, 2, 4, 4);
		g.fillRect(2, 8, 4, 4);
		g.fillRect(8, 8, 4, 4);
		g.dispose();
		return img;
	}

	private static BufferedImage drawMagnifier()
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(150, 150, 150));
		g.drawOval(2, 2, 7, 7);
		g.drawLine(9, 9, 12, 12);
		g.dispose();
		return img;
	}

	private static BufferedImage drawLines()
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(new Color(150, 150, 150));
		g.fillRect(2, 3, 10, 2);
		g.fillRect(2, 7, 10, 2);
		g.fillRect(2, 11, 10, 2);
		g.dispose();
		return img;
	}

	private static BufferedImage drawCard()
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setColor(new Color(150, 150, 150));
		g.drawRect(2, 2, 9, 9);
		g.drawLine(2, 6, 11, 6);
		g.dispose();
		return img;
	}

	private static BufferedImage drawImport()
	{
		BufferedImage img = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(150, 150, 150));
		g.drawLine(7, 2, 7, 8);
		g.drawLine(4, 5, 7, 8);
		g.drawLine(10, 5, 7, 8);
		g.drawLine(2, 9, 2, 11);
		g.drawLine(2, 11, 12, 11);
		g.drawLine(12, 9, 12, 11);
		g.dispose();
		return img;
	}

	private static BufferedImage drawNav()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		Polygon tag = new Polygon(
			new int[]{1, 8, 14, 14, 7, 1},
			new int[]{8, 1, 1, 8, 15, 15},
			6);
		g.setColor(new Color(219, 175, 76));
		g.fillPolygon(tag);
		g.setComposite(AlphaComposite.Clear);
		g.fillOval(10, 3, 3, 3);
		g.dispose();
		return image;
	}
}

package com.tagkeeper;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.ActionListener;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

class TagCard extends JPanel
{
	private static final Border NAME_BOTTOM_BORDER = new CompoundBorder(
		BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
		BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR));

	TagCard(TagkeeperPanel panel, TabKeeper tabKeeper, TagTransfer tagTransfer, ItemManager itemManager,
		TagData.TagInfo info, boolean active, boolean compact)
	{
		super(new BorderLayout());
		setBackground(ColorScheme.DARKER_GRAY_COLOR);

		String tag = info.getName();
		boolean isTab = info.isTab();

		Runnable toggleTab = () ->
		{
			if (isTab)
			{
				tabKeeper.removeTabFromBank(tag);
			}
			else
			{
				tabKeeper.addTabToBank(tag);
			}
		};

		if (compact)
		{
			buildCompact(itemManager, info, active, toggleTab);
		}
		else
		{
			buildStandard(panel, itemManager, info, active, toggleTab);
		}

		// names can truncate, so the tooltip leads with the full name
		setToolTipText("<html><b>" + tag + "</b><br>"
			+ (active ? "Click to close in the bank" : "Click to show in the bank") + "</html>");
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					panel.toggleTag(tag);
				}
			}
		});

		setComponentPopupMenu(buildPopupMenu(panel, tabKeeper, tagTransfer, tag, isTab, active, toggleTab));
	}

	private static JPopupMenu buildPopupMenu(TagkeeperPanel panel, TabKeeper tabKeeper,
		TagTransfer tagTransfer, String tag, boolean isTab, boolean active, Runnable toggleTab)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.add(menuItem(active ? "Close Tab" : "Open Tab", e -> panel.toggleTag(tag)));
		menu.add(menuItem(isTab ? "Remove Tab" : "Add Tab", e -> toggleTab.run()));
		menu.add(menuItem("Set Icon", e -> tabKeeper.promptChangeIcon(tag)));

		menu.addSeparator();

		menu.add(menuItem("Rename Tag", e -> tabKeeper.promptRename(tag)));
		JMenuItem deleteItem = menuItem("Delete Tag", e -> tabKeeper.promptDelete(tag));
		deleteItem.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
		menu.add(deleteItem);

		menu.addSeparator();

		menu.add(menuItem("Export to Clipboard", e -> tagTransfer.exportTag(tag)));
		return menu;
	}

	private static JMenuItem menuItem(String label, ActionListener action)
	{
		JMenuItem item = new JMenuItem(label);
		item.addActionListener(action);
		return item;
	}

	private void buildStandard(TagkeeperPanel panel, ItemManager itemManager,
		TagData.TagInfo info, boolean active, Runnable toggleTab)
	{
		String tag = info.getName();
		boolean isTab = info.isTab();

		JPanel nameSection = new JPanel(new BorderLayout());
		nameSection.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		nameSection.setBorder(NAME_BOTTOM_BORDER);
		nameSection.add(itemIcon(itemManager, info, 28, 30, 24, 21), BorderLayout.WEST);

		JLabel nameLabel = nameLabel(info, active);
		nameLabel.setPreferredSize(new Dimension(0, 30));
		nameSection.add(nameLabel, BorderLayout.CENTER);
		nameSection.add(countLabel(info), BorderLayout.EAST);
		add(nameSection, BorderLayout.NORTH);

		JPanel bottomContainer = new JPanel(new BorderLayout());
		bottomContainer.setBorder(new EmptyBorder(8, 0, 8, 0));
		bottomContainer.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JPanel indicators = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		indicators.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		indicators.add(tabButton(isTab, toggleTab));
		indicators.add(layoutIndicator(info));
		bottomContainer.add(indicators, BorderLayout.WEST);

		JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 4, 0));
		actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		actions.add(iconButton(
			active ? Icons.EYE : Icons.NO_EYE,
			active ? Icons.EYE_HOVER : Icons.NO_EYE_HOVER,
			active ? "Close this tag in the bank" : "Show this tag in the bank (bank must be open)",
			() -> panel.toggleTag(tag)));
		bottomContainer.add(actions, BorderLayout.EAST);
		add(bottomContainer, BorderLayout.CENTER);
	}

	private void buildCompact(ItemManager itemManager, TagData.TagInfo info, boolean active, Runnable toggleTab)
	{
		setBorder(new EmptyBorder(3, 4, 3, 6));
		add(itemIcon(itemManager, info, 22, 18, 20, 18), BorderLayout.WEST);

		JLabel nameLabel = nameLabel(info, active);
		nameLabel.setBorder(new EmptyBorder(0, 4, 0, 0));
		add(nameLabel, BorderLayout.CENTER);

		// GridBagLayout centers the row vertically, unlike FlowLayout which
		// tops it when the panel is stretched to the card height
		JPanel east = new JPanel(new GridBagLayout());
		east.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		GridBagConstraints gap = new GridBagConstraints();
		gap.insets = new Insets(0, 4, 0, 0);
		east.add(countLabel(info), new GridBagConstraints());
		east.add(tabButton(info.isTab(), toggleTab), gap);
		east.add(layoutIndicator(info), gap);
		add(east, BorderLayout.EAST);
	}

	private static JLabel tabButton(boolean isTab, Runnable toggleTab)
	{
		return iconButton(
			isTab ? Icons.TAB : Icons.NO_TAB,
			isTab ? Icons.TAB_HOVER : Icons.NO_TAB_HOVER,
			isTab ? "Remove tab from bank" : "Add tab to bank",
			toggleTab);
	}

	private static JLabel layoutIndicator(TagData.TagInfo info)
	{
		JLabel layoutIndicator = new JLabel(info.getLayoutItemCount() != null ? Icons.LAYOUT : Icons.NO_LAYOUT);
		layoutIndicator.setToolTipText(info.getLayoutItemCount() != null
			? "Has a layout (" + info.getLayoutItemCount() + " items)"
			: "No layout");
		return layoutIndicator;
	}

	private static JLabel itemIcon(ItemManager itemManager, TagData.TagInfo info,
		int width, int height, int imageWidth, int imageHeight)
	{
		JLabel iconLabel = new JLabel();
		iconLabel.setPreferredSize(new Dimension(width, height));
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		if (info.getIconItemId() != null)
		{
			AsyncBufferedImage image = itemManager.getImage(info.getIconItemId());
			image.onLoaded(() -> iconLabel.setIcon(new ImageIcon(ImageUtil.resizeImage(image, imageWidth, imageHeight))));
			iconLabel.setIcon(new ImageIcon(ImageUtil.resizeImage(image, imageWidth, imageHeight)));
		}
		return iconLabel;
	}

	private static JLabel nameLabel(TagData.TagInfo info, boolean active)
	{
		JLabel nameLabel = new JLabel(info.isHidden()
			? "<html>" + info.getName() + " <font color='#808080'>(hidden)</font></html>"
			: info.getName());
		nameLabel.setForeground(active ? ColorScheme.BRAND_ORANGE : Color.WHITE);
		nameLabel.setBorder(new EmptyBorder(0, 6, 0, 0));
		return nameLabel;
	}

	private static JLabel countLabel(TagData.TagInfo info)
	{
		JLabel countLabel = new JLabel(info.getItemCount() == 1 ? "1 item" : info.getItemCount() + " items");
		countLabel.setFont(FontManager.getRunescapeSmallFont());
		countLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		countLabel.setBorder(new EmptyBorder(0, 0, 0, 6));
		return countLabel;
	}

	private static JLabel iconButton(ImageIcon icon, ImageIcon hoverIcon, String tooltip, Runnable onClick)
	{
		JLabel label = new JLabel(icon);
		label.setToolTipText(tooltip);
		label.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					onClick.run();
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				label.setIcon(hoverIcon);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				label.setIcon(icon);
			}
		});
		return label;
	}
}

package com.tagkeeper;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.util.Text;

/**
 * Write-side tag operations: adds/removes tag tabs, renames and deletes
 * tags, and prompts via the in-game chatbox.
 */
@Slf4j
@Singleton
class TabKeeper
{
	private static final String USE_TABS_CONFIG = "useTabs";

	private final Client client;
	private final ClientThread clientThread;
	private final ConfigManager configManager;
	private final ChatboxPanelManager chatboxPanelManager;
	private final ChatboxItemSearch itemSearch;
	private final BankTagsService bankTagsService;
	private final TagManager tagManager;
	private final TagData tagData;
	private final IconShadows iconShadows;

	private boolean reEnableTabs;

	@Inject
	TabKeeper(Client client, ClientThread clientThread, ConfigManager configManager,
		ChatboxPanelManager chatboxPanelManager, ChatboxItemSearch itemSearch,
		BankTagsService bankTagsService, TagManager tagManager,
		TagData tagData, IconShadows iconShadows)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.configManager = configManager;
		this.chatboxPanelManager = chatboxPanelManager;
		this.itemSearch = itemSearch;
		this.bankTagsService = bankTagsService;
		this.tagManager = tagManager;
		this.tagData = tagData;
		this.iconShadows = iconShadows;
	}

	void addTabToBank(String tag)
	{
		tag = Text.standardize(tag);
		iconShadows.restoreIfMissing(tag);

		List<String> tabs = tagData.tabList();
		if (!tabs.contains(tag))
		{
			tabs.add(tag);
			saveTabList(tabs);
		}
		reinitBank();
	}

	void removeTabFromBank(String tag)
	{
		tag = Text.standardize(tag);
		iconShadows.snapshot(tag);

		List<String> tabs = tagData.tabList();
		if (tabs.remove(tag))
		{
			saveTabList(tabs);
		}
		// core TabManager.remove() also deletes the icon; mimic it
		configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(tag));
		reinitBank();
	}

	private void saveTabList(List<String> tabs)
	{
		configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_TABS_CONFIG, Text.toCSV(tabs));
	}

	void chatMessage(String message)
	{
		client.addChatMessage(ChatMessageType.CONSOLE, "", message, null);
	}

	String standardizedActiveTag()
	{
		return Text.standardize(TagData.nullToEmpty(bankTagsService.getActiveTag()));
	}

	/**
	 * Make the open bank re-read the tab list and icons: TabInterface only
	 * reloads them when useTabs flips, so switch it off and re-enable it on
	 * the resulting BANKMAIN_INIT (the Bank Tag Layouts plugin's trick).
	 */
	void reinitBank()
	{
		clientThread.invokeLater(() ->
		{
			if (client.getWidget(InterfaceID.Bankmain.UNIVERSE) == null)
			{
				// the next bank open reads config anyway
				return;
			}
			if ("false".equals(configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, USE_TABS_CONFIG)))
			{
				// tabs disabled by the user, or our own toggle already in
				// flight (which also debounces bursts of reinit requests)
				return;
			}
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, USE_TABS_CONFIG, false);
			reEnableTabs = true;
		});
	}

	// finishes the useTabs toggle; runs after TabInterface's own
	// BANKMAIN_INIT handling (priority -1 on the plugin's subscriber)
	void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() == ScriptID.BANKMAIN_INIT && reEnableTabs)
		{
			reEnableTabs = false;
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, USE_TABS_CONFIG, true);
		}
	}

	// restore the user's useTabs setting if the plugin stops mid-toggle
	void shutDown()
	{
		if (reEnableTabs)
		{
			reEnableTabs = false;
			configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, USE_TABS_CONFIG, true);
		}
	}

	static void showDialog(String message)
	{
		SwingUtilities.invokeLater(() ->
			JOptionPane.showMessageDialog(null, message, TagkeeperPlugin.PLUGIN_NAME, JOptionPane.WARNING_MESSAGE));
	}

	private static void notifyChatboxNeeded(String action)
	{
		showDialog(action + " uses the in-game chatbox - you need to be logged in.");
	}

	void promptChangeIcon(String tag)
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				notifyChatboxNeeded("Setting an icon");
				return;
			}
			itemSearch
				.tooltipText("Set icon for tag (" + tag + ")")
				.onItemSelected(itemId ->
				{
					// IconShadows sees the config change and updates the shadow copy
					configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(tag), itemId);
					reinitBank();
				})
				.build();
		});
	}

	void promptRename(String oldTag)
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				notifyChatboxNeeded("Renaming a tag");
				return;
			}
			chatboxPanelManager.openTextInput("Enter new tag name for tag \"" + oldTag + "\":")
				// core's FILTERED_CHARS, plus ',' which would corrupt the CSVs
				.addCharValidator(c -> "</>:,".indexOf(c) == -1)
				.onDone((Consumer<String>) name ->
					clientThread.invoke(() -> handleRenameInput(oldTag, name)))
				.build();
		});
	}

	private void handleRenameInput(String oldTag, String input)
	{
		String newTag = Text.standardize(input);
		if (newTag.isEmpty() || newTag.equals(oldTag))
		{
			return;
		}
		if (newTag.startsWith("_"))
		{
			showReservedNameNotice();
		}
		else if (tagData.tagExists(newTag))
		{
			promptMergeInto(oldTag, newTag);
		}
		else
		{
			renameTag(oldTag, newTag);
		}
	}

	private void showReservedNameNotice()
	{
		// the prefix marks plugin-internal machine tags; renaming onto one
		// would corrupt that plugin's data
		chatboxPanelManager.openTextMenuInput("Tag names starting with \"_\" are reserved for plugins.")
			.option("Ok", () ->
			{
			})
			.build();
	}

	private void promptMergeInto(String oldTag, String newTag)
	{
		chatboxPanelManager.openTextMenuInput("The tag \"" + newTag + "\" already exists.")
			.option("1. Merge \"" + oldTag + "\" into it.", () ->
				clientThread.invoke(() -> renameTag(oldTag, newTag)))
			.option("2. Cancel.", () ->
			{
			})
			.build();
	}

	void renameTag(String oldTag, String newTag)
	{
		boolean wasActive = oldTag.equals(standardizedActiveTag());

		renameItemTags(oldTag, newTag);

		List<String> renamedTabs = renameInTabList(tagData.tabList(), oldTag, newTag);
		if (renamedTabs != null)
		{
			saveTabList(renamedTabs);
		}

		moveTagConfigs(oldTag, newTag);

		if (wasActive)
		{
			bankTagsService.openBankTag(newTag, BankTagsService.OPTION_ALLOW_MODIFICATIONS);
		}
		reinitBank();
	}

	private void renameItemTags(String oldTag, String newTag)
	{
		for (String cfgKey : tagData.keysWithPrefix(BankTagsPlugin.CONFIG_GROUP, TagData.ITEM_KEY_PREFIX))
		{
			String updated = renameItemTagCsv(
				configManager.getConfiguration(BankTagsPlugin.CONFIG_GROUP, cfgKey), oldTag, newTag);
			if (updated != null)
			{
				configManager.setConfiguration(BankTagsPlugin.CONFIG_GROUP, cfgKey, updated);
			}
		}
	}

	private void moveTagConfigs(String oldTag, String newTag)
	{
		moveConfig(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(oldTag), TagData.iconKey(newTag));
		moveConfig(BankTagsPlugin.CONFIG_GROUP,
			BankTagsPlugin.TAG_LAYOUT_PREFIX + oldTag, BankTagsPlugin.TAG_LAYOUT_PREFIX + newTag);
		moveConfig(BankTagsPlugin.CONFIG_GROUP,
			TagData.TAG_HIDDEN_PREFIX + oldTag, TagData.TAG_HIDDEN_PREFIX + newTag);
		moveConfig(TagData.BTL_CONFIG_GROUP,
			TagData.BTL_LAYOUT_PREFIX + oldTag, TagData.BTL_LAYOUT_PREFIX + newTag);
		moveConfig(TagData.CONFIG_GROUP, TagData.shadowIconKey(oldTag), TagData.shadowIconKey(newTag));
	}

	void promptDelete(String tag)
	{
		clientThread.invoke(() ->
		{
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				notifyChatboxNeeded("Deleting a tag");
				return;
			}
			chatboxPanelManager.openTextMenuInput("Delete tag \"" + tag + "\" from all items?")
				.option("1. Delete tag, tab and layouts.", () ->
					clientThread.invoke(() -> deleteTag(tag)))
				.option("2. Cancel.", () ->
				{
				})
				.build();
		});
	}

	void deleteTag(String tag)
	{
		if (tag.equals(standardizedActiveTag()))
		{
			bankTagsService.closeBankTag();
		}

		tagManager.removeTag(tag);

		List<String> tabs = tagData.tabList();
		if (tabs.removeIf(t -> Text.standardize(t).equals(tag)))
		{
			saveTabList(tabs);
		}

		deleteTagConfigs(tag);
		reinitBank();
	}

	private void deleteTagConfigs(String tag)
	{
		configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.iconKey(tag));
		configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, BankTagsPlugin.TAG_LAYOUT_PREFIX + tag);
		configManager.unsetConfiguration(BankTagsPlugin.CONFIG_GROUP, TagData.TAG_HIDDEN_PREFIX + tag);
		configManager.unsetConfiguration(TagData.BTL_CONFIG_GROUP, TagData.BTL_LAYOUT_PREFIX + tag);
		configManager.unsetConfiguration(TagData.CONFIG_GROUP, TagData.shadowIconKey(tag));
	}


	// replaces oldTag in one item's tag CSV, keeping variation '*' suffixes;
	// returns null when the value did not contain oldTag
	static String renameItemTagCsv(String csv, String oldTag, String newTag)
	{
		Set<String> tags = new LinkedHashSet<>();
		boolean changed = false;
		for (String t : Text.fromCSV(TagData.nullToEmpty(csv)))
		{
			boolean var = t.endsWith(BankTagsPlugin.VAR_TAG_SUFFIX);
			String base = Text.standardize(TagData.stripVarSuffix(t));
			if (base.equals(oldTag))
			{
				tags.add(newTag + (var ? BankTagsPlugin.VAR_TAG_SUFFIX : ""));
				changed = true;
			}
			else
			{
				tags.add(base + (var ? BankTagsPlugin.VAR_TAG_SUFFIX : ""));
			}
		}
		return changed ? Text.toCSV(new ArrayList<>(tags)) : null;
	}

	// renames oldTag in place; a merge onto an existing tab drops the old
	// entry instead; returns null when oldTag was not a tab
	static List<String> renameInTabList(List<String> tabs, String oldTag, String newTag)
	{
		List<String> result = new ArrayList<>(tabs);
		int oldIdx = -1;
		boolean newPresent = false;
		for (int i = 0; i < result.size(); i++)
		{
			String std = Text.standardize(result.get(i));
			if (std.equals(oldTag))
			{
				oldIdx = i;
			}
			else if (std.equals(newTag))
			{
				newPresent = true;
			}
		}
		if (oldIdx < 0)
		{
			return null;
		}
		if (newPresent)
		{
			result.remove(oldIdx);
		}
		else
		{
			result.set(oldIdx, newTag);
		}
		return result;
	}

	// an existing value at the target key is kept (merge semantics)
	private void moveConfig(String group, String fromKey, String toKey)
	{
		String value = configManager.getConfiguration(group, fromKey);
		if (value == null)
		{
			return;
		}
		if (configManager.getConfiguration(group, toKey) == null)
		{
			configManager.setConfiguration(group, toKey, value);
		}
		configManager.unsetConfiguration(group, fromKey);
	}
}

package com.tagkeeper;

import javax.inject.Inject;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@PluginDescriptor(
	name = "Tagkeeper",
	description = "Overview of bank tags, tag tabs and bank layouts",
	tags = {"bank", "tags", "tabs", "layouts", "overview"}
)
@PluginDependency(BankTagsPlugin.class)
public class TagkeeperPlugin extends Plugin
{
	static final String PLUGIN_NAME = "Tagkeeper";

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private TagkeeperPanel panel;

	@Inject
	private TabKeeper tabKeeper;

	@Inject
	private IconShadows iconShadows;

	private NavigationButton navButton;

	@Override
	protected void startUp()
	{
		iconShadows.snapshotAll();
		iconShadows.gc();

		navButton = NavigationButton.builder()
			.tooltip(PLUGIN_NAME)
			.icon(Icons.NAV)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel.shutDown();
		tabKeeper.shutDown();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (BankTagsPlugin.CONFIG_GROUP.equals(event.getGroup()))
		{
			if (iconShadows.onBankTagsConfigChanged(event))
			{
				tabKeeper.reinitBank();
			}
			panel.reloadSoon();
		}
		else if (TagData.BTL_CONFIG_GROUP.equals(event.getGroup()))
		{
			panel.reloadSoon();
		}
	}

	// after TabInterface's own BANKMAIN_INIT handling
	@Subscribe(priority = -1f)
	public void onScriptPreFired(ScriptPreFired event)
	{
		tabKeeper.onScriptPreFired(event);
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		// the new profile has its own tags and shadow copies
		iconShadows.snapshotAll();
		iconShadows.gc();
		panel.reloadSoon();
	}
}
